import pandas as pd

def weather_type(countries: pd.DataFrame, weather: pd.DataFrame) -> pd.DataFrame:
    w = weather[(weather['day'] >= '2019-11-01') & (weather['day'] <= '2019-11-30')]
    merged = w.merge(countries, on='country_id', how='inner')
    avg = merged.groupby('country_name')['weather_state'].mean().reset_index()
    def label(x):
        if x <= 15:
            return 'Cold'
        if x >= 25:
            return 'Hot'
        return 'Warm'
    avg['weather_type'] = avg['weather_state'].apply(label)
    return avg[['country_name', 'weather_type']]

