#include <bits/stdc++.h>
using namespace std;

// LeetCode SQL problems are not solvable in C++ via class Solution;
// equivalent logic shown as a standalone function.
vector<pair<string,string>> weatherType(
    vector<tuple<int,string>>& countries,
    vector<tuple<int,int,string>>& weather) {
    unordered_map<int,string> name;
    for (auto& [id, nm] : countries) name[id] = nm;
    unordered_map<int,pair<long long,int>> agg;
    for (auto& [id, state, day] : weather) {
        if (day >= "2019-11-01" && day <= "2019-11-30") {
            agg[id].first += state;
            agg[id].second++;
        }
    }
    vector<pair<string,string>> res;
    for (auto& [id, p] : agg) {
        double avg = (double)p.first / p.second;
        string t = avg <= 15 ? "Cold" : (avg >= 25 ? "Hot" : "Warm");
        res.push_back({name[id], t});
    }
    return res;
}

