import java.util.*;

class Solution {
    public List<String[]> weatherType(int[][] countriesInfo, String[] countryNames,
                                      int[][] wIds, int[][] states, String[] days) {
        Map<Integer, String> names = new HashMap<>();
        for (int i = 0; i < countriesInfo.length; i++)
            names.put(countriesInfo[i][0], countryNames[i]);
        Map<Integer, long[]> agg = new HashMap<>();
        for (int i = 0; i < wIds.length; i++) {
            if (days[i].compareTo("2019-11-01") >= 0 && days[i].compareTo("2019-11-30") <= 0) {
                long[] a = agg.computeIfAbsent(wIds[i][0], k -> new long[2]);
                a[0] += states[i][0];
                a[1]++;
            }
        }
        List<String[]> res = new ArrayList<>();
        for (Map.Entry<Integer, long[]> e : agg.entrySet()) {
            double avg = (double) e.getValue()[0] / e.getValue()[1];
            String t = avg <= 15 ? "Cold" : (avg >= 25 ? "Hot" : "Warm");
            res.add(new String[]{names.get(e.getKey()), t});
        }
        return res;
    }
}

