/**
 * @param {number[][]} countriesInfo - [country_id]
 * @param {string[]} countryNames
 * @param {number[]} wCountryIds
 * @param {number[]} states
 * @param {string[]} days
 */
var weatherType = function(countriesInfo, countryNames, wCountryIds, states, days) {
    const names = new Map();
    countriesInfo.forEach((c, i) => names.set(c[0], countryNames[i]));
    const agg = new Map();
    for (let i = 0; i < wCountryIds.length; i++) {
        if (days[i] >= '2019-11-01' && days[i] <= '2019-11-30') {
            const a = agg.get(wCountryIds[i]) || [0, 0];
            a[0] += states[i];
            a[1]++;
            agg.set(wCountryIds[i], a);
        }
    }
    const res = [];
    for (const [id, [sum, cnt]] of agg) {
        const avg = sum / cnt;
        const t = avg <= 15 ? 'Cold' : (avg >= 25 ? 'Hot' : 'Warm');
        res.push([names.get(id), t]);
    }
    return res;
};

